#include <hb-ot.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <font_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) { perror("fopen"); return 1; }
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *data = malloc(size);
    fread(data, 1, size, f);
    fclose(f);

    hb_blob_t *blob = hb_blob_create(data, size, HB_MEMORY_MODE_READONLY, NULL, NULL);
    hb_face_t *face = hb_face_create(blob, 0);
    hb_font_t *font = hb_font_create(face);
    hb_ot_font_set_funcs(font);
    hb_font_set_scale(font, 12, 12);

    /* Test get_glyph_name and get_glyph_from_name */
    char buf[5] = {0};
    hb_codepoint_t g;

    for (hb_codepoint_t cp = 0; cp < 10; cp++) {
        memset(buf, 0, sizeof(buf));
        if (hb_font_get_glyph_name(font, cp, buf, sizeof(buf))) {
            printf("Glyph %u: name='%s' (len=%zu)\n", cp, buf, strlen(buf));
            if (strlen(buf) > 0) {
                if (hb_font_get_glyph_from_name(font, buf, strlen(buf), &g)) {
                    printf("  -> glyph %u\n", g);
                }
            }
        }
    }

    hb_font_destroy(font);
    hb_face_destroy(face);
    hb_blob_destroy(blob);
    free(data);
    return 0;
}
EOF

